import {
    LogicWrapper,
    MakeLogicType,
    actions,
    afterMount,
    getContext,
    kea,
    key,
    listeners,
    path,
    props,
    propsChanged,
    reducers,
} from 'kea'

import { DisposablesManager } from '~/kea-disposables'

import { RegexCheck, RegexMatchingResult, startRegexMatching } from './regexMatching'

export type RegexPreviewState = { status: 'idle' } | { status: 'pending' } | RegexMatchingResult

export interface RegexMatchingLogicProps {
    instanceKey: string
    checks: RegexCheck[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface regexMatchingLogicValues {
    preview: RegexPreviewState
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface regexMatchingLogicActions {
    refresh: () => {
        value: true
    }
    setPreview: (preview: RegexPreviewState) => {
        preview: RegexPreviewState
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface regexMatchingLogicMeta {
    key: string
}

export type regexMatchingLogicType = MakeLogicType<
    regexMatchingLogicValues,
    regexMatchingLogicActions,
    RegexMatchingLogicProps,
    regexMatchingLogicMeta
>

export const regexMatchingLogic: LogicWrapper<regexMatchingLogicType> = kea<regexMatchingLogicType>([
    props({} as RegexMatchingLogicProps),
    key((props) => props.instanceKey),
    path((key) => ['lib', 'regex', 'regexMatchingLogic', key]),
    actions({ refresh: true, setPreview: (preview: RegexPreviewState) => ({ preview }) }),
    reducers({ preview: [{ status: 'idle' } as RegexPreviewState, { setPreview: (_, { preview }) => preview }] }),
    listeners(({ actions, props, cache }) => ({
        refresh: () => {
            const fingerprint = JSON.stringify(props.checks)
            if (cache.fingerprint === fingerprint) {
                return
            }
            cache.fingerprint = fingerprint
            const manager: DisposablesManager = cache.disposables
            manager.dispose('matching')
            if (!props.checks.length) {
                actions.setPreview({ status: 'idle' })
                return
            }
            actions.setPreview({ status: 'pending' })
            const context = getContext()
            manager.add(
                () => {
                    let active = true
                    const request = startRegexMatching(props.checks)
                    void request.promise.then((result) => {
                        if (!active || manager.isDisposed || getContext() !== context) {
                            return
                        }
                        manager.dispose('matching')
                        actions.setPreview(result)
                    })
                    return () => {
                        active = false
                        request.cancel()
                    }
                },
                'matching',
                { pauseOnPageHidden: false }
            )
        },
    })),
    afterMount(({ actions, cache }) => {
        cache.fingerprint = undefined
        actions.refresh()
    }),
    propsChanged(({ actions, props }, oldProps) => {
        if (JSON.stringify(props.checks) !== JSON.stringify(oldProps.checks)) {
            actions.refresh()
        }
    }),
])
